const test=require('node:test'),assert=require('node:assert/strict');
test('neighborhood and town have distinct occupied street blocks with one residential district',async()=>{
 const {settlementDistrictEntries,districtTopology}=await import('../settlement-districts.js'),{settlementPreset}=await import('../settlement-presets.js');
 const neighborhood=settlementDistrictEntries('neighborhood'),town=settlementDistrictEntries('town');assert.equal(neighborhood.length,7);assert.equal(town.length,9);
 for(const [name,entries]of [['neighborhood',neighborhood],['town',town]]){const topology=districtTopology(entries);assert(topology.connected);assert.equal(topology.residentialCards,1);assert.equal(entries[topology.core].type,name);assert(topology.throughCells>=entries.length-1);assert(entries.some(e=>e.type==='gathering'&&e.q===1&&e.r===0));assert(!entries.some(e=>e.type==='home'));assert.deepEqual(settlementPreset(name).entries,entries);for(const type of ['garden','woodland','pottery','preservation'])assert(entries.some(e=>e.type===type));}
 const positions=entries=>entries.map(e=>e.q+','+e.r).sort();assert.notDeepEqual(positions(neighborhood),positions(settlementPreset('hamlet').entries));assert.notDeepEqual(positions(town),positions(neighborhood));
 neighborhood[0].seed=999;assert.equal(settlementDistrictEntries('neighborhood')[0].seed,41);
});
test('topology reports adjacency only, rejects overlaps and does not claim route verification',async()=>{
 const {districtTopology}=await import('../settlement-districts.js');assert.throws(()=>districtTopology([{q:0,r:0},{q:0,r:0}]),/overlapping/);assert.equal(districtTopology([{q:0,r:0},{q:2,r:0}]).connected,false);assert.equal(districtTopology([]).connected,false);assert.match(districtTopology([{q:0,r:0}]).scope,/actual terrain.*preflight/);
});
test('actual dense district presets certify every working route without adding simulated residents',async()=>{
 const fs=require('node:fs'),path=require('node:path'),root=path.join(__dirname,'..'),{settlementDistrictEntries}=await import('../settlement-districts.js'),{districtRecipe,DISTRICT_SCENES}=await import('../district-scenes.js'),{domesticRecipe,DOMESTIC_SCENES}=await import('../domestic-scenes.js'),{planSettlementPreset}=await import('../settlement-layout.js'),{evolveBoardEconomy,resolveBoardEconomy}=await import('../board-economy.js');
 const assetIndex=JSON.parse(fs.readFileSync(path.join(root,'domestic-assets/index.json'),'utf8')),catalog=JSON.parse(fs.readFileSync(path.join(root,'simulation-assets/catalog.json'),'utf8')),tree=catalog.find(x=>x.id==='tree-standing'),parts=JSON.parse(fs.readFileSync(path.join(root,tree.json),'utf8')),xs=[],zs=[];for(const p of parts)for(let i=0;i<p.positions.length;i+=3){xs.push(p.positions[i]);zs.push(p.positions[i+2]);}const dimensions={'tree-standing':{w:2*(Math.max(...xs)-Math.min(...xs)),d:2*(Math.max(...zs)-Math.min(...zs))}};
 for(const type of ['neighborhood','town']){
  const entries=settlementDistrictEntries(type),cards=entries.map((e,i)=>({id:e.type+'-'+i,revision:1,rendition:{meshes:[]},cells:[{q:0,r:0}],recipe:DISTRICT_SCENES[e.type]?districtRecipe(e.type,e.preset,e.seed):domesticRecipe(e.type,e.preset,e.seed),capabilities:(DISTRICT_SCENES[e.type]||DOMESTIC_SCENES[e.type]).capabilities})),saved=structuredClone(cards),result=planSettlementPreset({cards,entries,assetIndex,dimensions});
  assert.equal(result.status,'ready',JSON.stringify(result.warnings));assert(result.attempts.length>0);assert.equal(result.perCard.filter(c=>c.status==='connected').length,entries.length);assert.deepEqual(result.warnings,[]);assert.equal(result.board.population,6);assert.equal(result.economy.report.capacities.housing,6);assert.deepEqual(cards,saved);
  const district=result.assembly.plans.find(p=>p.type===type),macro=district.placements[0];assert.equal(macro.accessScope,'working-entrances');assert.equal(macro.items.filter(i=>i.asset==='GF-191').length,type==='town'?8:4);assert.equal(district.paths.filter(p=>p.kind==='courtyard').length,macro.internalPaths.length);assert.equal(result.perCard[0].accessScope,'working-entrances');if(type==='town'){const joins=district.paths.filter(p=>p.purpose==='through-street join');assert(joins.length>0,'Town north street must actually meet an outer lane');assert(joins.every(p=>Math.hypot(p.points[1].x-p.points[0].x,p.points[1].z-p.points[0].z)<=macro.radius));
   const {resolvedAssemblyObstacles}=await import('../board-resolved-access.js'),{createJoinVerifier}=await import('../board-join-verifier.js'),{containsBoardPoint}=await import('../board-bounds.js'),{dressingPlan,landscapeSettings}=await import('../tile-landscape.js'),{boardTiles}=await import('../board-terrain.js'),{cardKey}=await import('../playground-model.js');
   const inventory=resolvedAssemblyObstacles(result.assembly,item=>{if(['soil','roof'].includes(item.asset))return {passable:true};const b=assetIndex[item.asset]?.bounds;return b?{kind:'box',w:2*Math.max(Math.abs(b.min[0]),Math.abs(b.max[0])),d:2*Math.max(Math.abs(b.min[1]),Math.abs(b.max[1]))}:null;}),tiles=boardTiles(result.board);
   for(const plan of result.assembly.plans){const tile=tiles.find(t=>t.id===plan.id),instance=result.board.instances.find(i=>i.instanceId===tile.instanceId),card=result.board.cards[cardKey(instance.cardId,instance.cardRevision)];for(const d of dressingPlan(plan,landscapeSettings({landscape:card.recipe.landscape}))){if(d.kind==='grass')continue;let radius;if(['tree','prop'].includes(d.kind)){const size=(plan.renderedDimensions||dimensions)[d.model||'tree-standing'];assert(size);radius=Math.hypot(size.w,size.d)/2*(d.kind==='tree'?d.size:1);}else radius=d.kind==='rock'?.55+.45*d.size:.55+.9*d.size;inventory.obstacles.push({kind:'circle',x:plan.center.x+d.x,z:plan.center.z+d.z,radius});}}
   assert(inventory.complete);const verify=createJoinVerifier({boardId:result.board.id,boardRevision:result.board.revision,heightAt:result.heightAt,contains:containsBoardPoint,obstacles:inventory.obstacles,obstaclesComplete:true});
   for(const join of joins){const [a,b]=join.points,length=Math.hypot(b.x-a.x,b.z-a.z),count=Math.ceil(length/6);for(let i=0;i<count;i++){const at=t=>{const x=district.center.x+a.x+(b.x-a.x)*t,z=district.center.z+a.z+(b.z-a.z)*t;return {x,z,y:result.heightAt(x,z)};};assert(verify({signature:'through-street-'+i,access:{a:at(i/count),b:at((i+1)/count)}},result.board),'Through join must independently pass complete actual terrain and obstacle inventory');}}
}
  let board=evolveBoardEconomy(result.board,result.economy,'supplies'),economic=resolveBoardEconomy(board,result.assembly,result.heightAt,assetIndex,dimensions);board=evolveBoardEconomy(board,economic,'day',{days:6});economic=resolveBoardEconomy(board,result.assembly,result.heightAt,assetIndex,dimensions);assert.equal(economic.report.population,6);assert(economic.report.lastDay.workersUsed<=6);assert(economic.report.goals.every(g=>g.ready));
  const broken=cards.map((c,i)=>i?c:{...c,recipe:{...c.recipe,requirements:c.recipe.requirements.map(r=>({...r,internalPaths:[]}))}}),rejected=planSettlementPreset({cards:broken,entries,assetIndex,dimensions,sites:[{q:-4,r:3}]});assert.equal(rejected.status,'blocked');assert(rejected.warnings.length);
 }
});
